pub fn edt(f: &mut [f32], d: &mut [f32], z: &mut [f32], w: &mut [u16], n: usize) {
    let mut k = 0;
    let mut s: f32;
    w[0] = 0;
    z[0] = -INF;
    z[1] = INF;
    for q in 1..n {
        s = ((f[q] + (q as f32 * q as f32)) - (f[w[k] as usize] + (w[k] as f32 * w[k] as f32))) / (2 * q as f32 - 2 * w[k] as f32);
        while s <= z[k] {
            k -= 1;
            s = ((f[q] + (q as f32 * q as f32)) - (f[w[k] as usize] + (w[k] as f32 * w[k] as f32))) / (2 * q as f32 - 2 * w[k] as f32);
        }
        k += 1;
        w[k] = q as u16;
        z[k] = s;
        z[k + 1] = INF;
    }
    k = 0;
    for q in 0..n {
        while z[k + 1] < q as f32 {
            k += 1;
        }
        d[q] = ((q as f32 - w[k] as f32) * (q as f32 - w[k] as f32)) + f[w[k] as usize];
    }
}

