    let index = perm_grad_index_3d[(perm[(perm[(xsb & 0xFF) as usize] + ysb) as usize & 0xFF] + zsb) as usize & 0xFF] as usize;
    GRADIENTS_3D[index] as f64 * dx + GRADIENTS_3D[index + 1] as f64 * dy + GRADIENTS_3D[index + 2] as f64 * dz
}

pub fn extrapolate4(ctx: &OsnContext, xsb: i32, ysb: i32, zsb: i32, wsb: i32, dx: f64, dy: f64, dz: f64, dw: f64) -> f64 {
