    GRADIENTS_4D[index] as f64 * dx + GRADIENTS_4D[index + 1] as f64 * dy + GRADIENTS_4D[index + 2] as f64 * dz + GRADIENTS_4D[index + 3] as f64 * dw
}

pub fn allocate_perm(ctx: &mut OsnContext, nperm: usize, ngrad: usize) -> i32 {
    ctx.perm.clear();
    ctx.perm_grad_index_3d.clear();

    ctx.perm = vec![0; nperm];
    if ctx.perm.is_empty() {
        return -12;
    }

    ctx.perm_grad_index_3d = vec![0; ngrad];
    if ctx.perm_grad_index_3d.is_empty() {
        ctx.perm.clear();
        return -12;
    }

    0
}

