pub fn km_quaternion_rotation_pitch_yaw_roll(
    p_out: &mut KmQuaternion,
    pitch: f32,
    yaw: f32,
    roll: f32,
) -> &KmQuaternion {
    assert!(pitch <= 2.0 * PI, "pitch <= 2*kmPI");
    assert!(yaw <= 2.0 * PI, "yaw <= 2*kmPI");
    assert!(roll <= 2.0 * PI, "roll <= 2*kmPI");

    let s_y = (yaw * 0.5).sin();
    let c_y = (yaw * 0.5).cos();
    let s_z = (roll * 0.5).sin();
    let c_z = (roll * 0.5).cos();
    let s_x = (pitch * 0.5).sin();
    let c_x = (pitch * 0.5).cos();

    p_out.w = c_y * c_z * c_x - s_y * s_z * s_x;
    p_out.x = s_y * s_z * c_x + c_y * c_z * s_x;
    p_out.y = s_y * c_z * c_x + c_y * s_z * s_x;
    p_out.z = c_y * s_z * c_x - s_y * c_z * s_x;

    p_out
}

