use std::f32::consts::SQRT_2;

pub fn km_mat4_extract_plane(p_out: &mut KmPlane, p_in: &KmMat4, plane: u32) -> &mut KmPlane {
    match plane {
        1 => {
            p_out.a = p_in.mat[3] - p_in.mat[0];
            p_out.b = p_in.mat[7] - p_in.mat[4];
            p_out.c = p_in.mat[11] - p_in.mat[8];
            p_out.d = p_in.mat[15] - p_in.mat[12];
        }
        0 => {
            p_out.a = p_in.mat[3] + p_in.mat[0];
            p_out.b = p_in.mat[7] + p_in.mat[4];
            p_out.c = p_in.mat[11] + p_in.mat[8];
            p_out.d = p_in.mat[15] + p_in.mat[12];
        }
        2 => {
            p_out.a = p_in.mat[3] + p_in.mat[1];
            p_out.b = p_in.mat[7] + p_in.mat[5];
            p_out.c = p_in.mat[11] + p_in.mat[9];
            p_out.d = p_in.mat[15] + p_in.mat[13];
        }
        3 => {
            p_out.a = p_in.mat[3] - p_in.mat[1];
            p_out.b = p_in.mat[7] - p_in.mat[5];
            p_out.c = p_in.mat[11] - p_in.mat[9];
            p_out.d = p_in.mat[15] - p_in.mat[13];
        }
        5 => {
            p_out.a = p_in.mat[3] - p_in.mat[2];
            p_out.b = p_in.mat[7] - p_in.mat[6];
            p_out.c = p_in.mat[11] - p_in.mat[10];
            p_out.d = p_in.mat[15] - p_in.mat[14];
        }
        4 => {
            p_out.a = p_in.mat[3] + p_in.mat[2];
            p_out.b = p_in.mat[7] + p_in.mat[6];
            p_out.c = p_in.mat[11] + p_in.mat[10];
            p_out.d = p_in.mat[15] + p_in.mat[14];
        }
        _ => panic!("Invalid plane index"),
    }

    let t = (p_out.a * p_out.a + p_out.b * p_out.b + p_out.c * p_out.c).sqrt();
    p_out.a /= t;
    p_out.b /= t;
    p_out.c /= t;
    p_out.d /= t;

    p_out
}

pub fn km_vec4_transform(p_out: &mut KmVec4, p_v: &KmVec4, p_m: &KmMat4) -> &mut KmVec4 {
