pub fn km_vec4_transform_array(
    p_out: &mut [KmVec4],
    out_stride: usize,
    p_v: &[KmVec4],
    v_stride: usize,
    p_m: &KmMat4,
    count: usize,
) {
    for i in 0..count {
        let v_index = i * v_stride;
        let out_index = i * out_stride;

        let vec = &p_v[v_index];
        let transformed_vec = KmVec4 {
            x: vec.x * p_m.mat[0] + vec.y * p_m.mat[4] + vec.z * p_m.mat[8] + vec.w * p_m.mat[12],
            y: vec.x * p_m.mat[1] + vec.y * p_m.mat[5] + vec.z * p_m.mat[9] + vec.w * p_m.mat[13],
            z: vec.x * p_m.mat[2] + vec.y * p_m.mat[6] + vec.z * p_m.mat[10] + vec.w * p_m.mat[14],
            w: vec.x * p_m.mat[3] + vec.y * p_m.mat[7] + vec.z * p_m.mat[11] + vec.w * p_m.mat[15],
        };

        p_out[out_index] = transformed_vec;
    }
}

