pub fn km_mat3_adjugate(p_out: &mut KmMat3, p_in: &KmMat3) -> &KmMat3 {
    p_out.mat[0] = p_in.mat[4] * p_in.mat[8] - p_in.mat[5] * p_in.mat[7];
    p_out.mat[1] = p_in.mat[2] * p_in.mat[7] - p_in.mat[1] * p_in.mat[8];
    p_out.mat[2] = p_in.mat[1] * p_in.mat[5] - p_in.mat[2] * p_in.mat[4];
    p_out.mat[3] = p_in.mat[5] * p_in.mat[6] - p_in.mat[3] * p_in.mat[8];
    p_out.mat[4] = p_in.mat[0] * p_in.mat[8] - p_in.mat[2] * p_in.mat[6];
    p_out.mat[5] = p_in.mat[2] * p_in.mat[3] - p_in.mat[0] * p_in.mat[5];
    p_out.mat[6] = p_in.mat[3] * p_in.mat[7] - p_in.mat[4] * p_in.mat[6];
    p_out.mat[7] = p_in.mat[1] * p_in.mat[6] - p_in.mat[0] * p_in.mat[7];
