pub fn km_mat3_determinant(p_in: &KmMat3) -> f32 {
    let output = p_in.mat[0] * p_in.mat[4] * p_in.mat[8] 
               + p_in.mat[1] * p_in.mat[5] * p_in.mat[6] 
               + p_in.mat[2] * p_in.mat[3] * p_in.mat[7]
               - p_in.mat[2] * p_in.mat[4] * p_in.mat[6] 
               - p_in.mat[0] * p_in.mat[5] * p_in.mat[7] 
               - p_in.mat[1] * p_in.mat[3] * p_in.mat[8];
    output
}

