pub fn km_quaternion_multiply_vec3(p_out: &mut KmVec3, q: &KmQuaternion, v: &KmVec3) {
    // Quaternion multiplication logic to transform the vector `v` using quaternion `q`
    let qv = KmQuaternion {
        x: v.x,
        y: v.y,
        z: v.z,
        w: 0.0,
    };

    let q_conjugate = KmQuaternion {
        x: -q.x,
        y: -q.y,
        z: -q.z,
        w: q.w,
    };

    let result = quaternion_multiply(quaternion_multiply(q, &qv), &q_conjugate);

    p_out.x = result.x;
    p_out.y = result.y;
    p_out.z = result.z;
}

fn quaternion_multiply(a: &KmQuaternion, b: &KmQuaternion) -> KmQuaternion {
    KmQuaternion {
        x: a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
        y: a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
        z: a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w,
        w: a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
    }
}

