pub fn km_plane_from_points(p_out: &mut KmPlane, p1: &KmVec3, p2: &KmVec3, p3: &KmVec3) -> &KmPlane {
    // Calculate the vectors from the points
    let u = KmVec3 {
        x: p2.x - p1.x,
        y: p2.y - p1.y,
        z: p2.z - p1.z,
    };
    let v = KmVec3 {
        x: p3.x - p1.x,
        y: p3.y - p1.y,
        z: p3.z - p1.z,
    };

    // Calculate the cross product of u and v
    let normal = KmVec3 {
        x: u.y * v.z - u.z * v.y,
        y: u.z * v.x - u.x * v.z,
        z: u.x * v.y - u.y * v.x,
    };

    // Calculate the plane coefficients
    p_out.a = normal.x;
    p_out.b = normal.y;
    p_out.c = normal.z;
    p_out.d = -(normal.x * p1.x + normal.y * p1.y + normal.z * p1.z);

    p_out
}

