pub fn km_vec3_get_horizontal_angle(p_out: &mut KmVec3, p_in: &KmVec3) -> &mut KmVec3 {
    let z1 = (p_in.x * p_in.x + p_in.z * p_in.z).sqrt();
    p_out.y = km_radians_to_degrees(p_in.x.atan2(p_in.z));
    if p_out.y < 0.0 {
        p_out.y += 360.0;
    }
    if p_out.y >= 360.0 {
        p_out.y -= 360.0;
    }
    p_out.x = km_radians_to_degrees(z1.atan2(p_in.y)) - 90.0;
    if p_out.x < 0.0 {
        p_out.x += 360.0;
    }
    if p_out.x >= 360.0 {
        p_out.x -= 360.0;
    }
    p_out
}

pub fn km_vec3_rotation_to_direction(p_out: &mut KmVec3, p_in: &KmVec3, forwards: &KmVec3) -> &KmVec3 {
    let xr = km_degrees_to_radians(p_in.x);
    let yr = km_degrees_to_radians(p_in.y);
    let zr = km_degrees_to_radians(p_in.z);
    let cr = xr.cos();
    let sr = xr.sin();
    let cp = yr.cos();
    let sp = yr.sin();
    let cy = zr.cos();
    let sy = zr.sin();
    let srsp = sr * sp;
    let crsp = cr * sp;
    let pseudo_matrix = [
        (cp * cy), (cp * sy), (-sp),
        (srsp * cy - cr * sy), (srsp * sy + cr * cy), (sr * cp),
        (crsp * cy + sr * sy), (crsp * sy - sr * cy), (cr * cp),
    ];
    p_out.x = forwards.x * pseudo_matrix[0] + forwards.y * pseudo_matrix[3] + forwards.z * pseudo_matrix[6];
    p_out.y = forwards.x * pseudo_matrix[1] + forwards.y * pseudo_matrix[4] + forwards.z * pseudo_matrix[7];
    p_out.z = forwards.x * pseudo_matrix[2] + forwards.y * pseudo_matrix[5] + forwards.z * pseudo_matrix[8];
    p_out
}

