pub fn km_line2_with_line_intersection(
    pt_a: &KmVec2,
    vec_a: &KmVec2,
    pt_b: &KmVec2,
    vec_b: &KmVec2,
    out_ta: Option<&mut f32>,
    out_tb: Option<&mut f32>,
    out_intersection: Option<&mut KmVec2>,
) -> u8 {
    let x1 = pt_a.x;
    let y1 = pt_a.y;
    let x2 = x1 + vec_a.x;
    let y2 = y1 + vec_a.y;
    let x3 = pt_b.x;
    let y3 = pt_b.y;
    let x4 = x3 + vec_b.x;
    let y4 = y3 + vec_b.y;
    let denom = (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1);

    if denom > -0.0001 && denom < 0.0001 {
        return 0;
    }

    let ua = ((x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)) / denom;
    let ub = ((x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3)) / denom;
    let x = x1 + ua * (x2 - x1);
    let y = y1 + ua * (y2 - y1);

    if let Some(out_ta) = out_ta {
        *out_ta = ua;
    }
    if let Some(out_tb) = out_tb {
        *out_tb = ub;
    }
    if let Some(out_intersection) = out_intersection {
        out_intersection.x = x;
        out_intersection.y = y;
    }

    1
}

