pub fn km_vec2_rotate_by(p_out: &mut KmVec2, p_in: &KmVec2, degrees: f32, center: &KmVec2) -> &mut KmVec2 {
    let radians = km_degrees_to_radians(degrees);
    let cs = radians.cos();
    let sn = radians.sin();

    p_out.x = p_in.x - center.x;
    p_out.y = p_in.y - center.y;

    let x = p_out.x * cs - p_out.y * sn;
    let y = p_out.x * sn + p_out.y * cs;

    p_out.x = x + center.x;
    p_out.y = y + center.y;

    p_out
}

pub fn heman_export_u8(source: &HemanImage, minv: f32, maxv: f32, outp: &mut [HemanByte]) {
    let inp = &source.data;
    let scale = 1.0 / (maxv - minv);
    let size = (source.height * source.width * source.nbands) as usize;
    for i in 0..size {
        let v = 255.0 * (inp[i] - minv) * scale;
        outp[i] = if v < 0.0 {
            0
        } else if v > 255.0 {
            255
        } else {
            v as HemanByte
        };
    }
}

