pub fn heman_image_texel(img: &HemanImage, x: i32, y: i32) -> Option<&[f32]> {
    let index = (y * img.width * img.nbands + x * img.nbands) as usize;
    let end_index = index + img.nbands as usize;
    if index < img.data.len() && end_index <= img.data.len() {
