pub fn heman_ops_accumulate(dst: &mut HemanImage, src: &HemanImage) {
    assert_eq!(dst.nbands, src.nbands, "dst.nbands must be equal to src.nbands");
    assert_eq!(dst.width, src.width, "dst.width must be equal to src.width");
    assert_eq!(dst.height, src.height, "dst.height must be equal to src.height");

    let size = dst.height * dst.width;
    let sdata = &src.data;
    let ddata = &mut dst.data;

    for i in 0..size as usize {
        ddata[i] += sdata[i];
    }
}

pub fn match_pixel(mask: &HemanImage, mask_color: HemanColor, invert_mask: i32, pixel_index: usize) -> i32 {
    let mcolor = &mask.data[pixel_index * 3..pixel_index * 3 + 3];
    let r1 = (mcolor[0] * 255.0) as u8;
    let g1 = (mcolor[1] * 255.0) as u8;
    let b1 = (mcolor[2] * 255.0) as u8;
    let r2 = (mask_color >> 16) as u8;
    let g2 = ((mask_color >> 8) & 0xff) as u8;
    let b2 = (mask_color & 0xff) as u8;
    let retval = (r1 == r2 && g1 == g2 && b1 == b2) as i32;
    if invert_mask != 0 {
        1 - retval
    } else {
        retval
    }
}

