pub fn transform_to_distance(sdf: &mut HemanImage) {
    let width = sdf.width as usize;
    let height = sdf.height as usize;
    let size = width * height;
    let mut ff = vec![0.0f32; size];
    let mut dd = vec![0.0f32; size];
    let mut zz = vec![0.0f32; (height + 1) * (width + 1)];
    let mut ww = vec![0u16; size];

    let sdf_data = Arc::new(sdf.data.clone());

    let mut handles = vec![];

    for x in 0..width {
        let sdf_data = Arc::clone(&sdf_data);
        let handle = thread::spawn(move || {
            let f = &mut ff[height * x..height * (x + 1)];
            let d = &mut dd[height * x..height * (x + 1)];
            let z = &mut zz[(height + 1) * x..(height + 1) * (x + 1)];
            let w = &mut ww[height * x..height * (x + 1)];
            for y in 0..height {
                f[y] = sdf_data[y * width + x];
            }
            edt(f, d, z, w, height);
            for y in 0..height {
                sdf_data[y * width + x] = d[y];
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    handles.clear();

    for y in 0..height {
        let sdf_data = Arc::clone(&sdf_data);
        let handle = thread::spawn(move || {
            let f = &mut ff[width * y..width * (y + 1)];
            let d = &mut dd[width * y..width * (y + 1)];
            let z = &mut zz[(width + 1) * y..(width + 1) * (y + 1)];
            let w = &mut ww[width * y..width * (y + 1)];
            for x in 0..width {
                f[x] = sdf_data[y * width + x];
            }
            edt(f, d, z, w, width);
            for x in 0..width {
                sdf_data[y * width + x] = d[x];
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }
}

