    let mut ysv_ext0;
    let mut zsv_ext0;
    let mut xsv_ext1;
    let mut ysv_ext1;
    let mut zsv_ext1;

    let mut value = 0.0;

    if in_sum <= 1.0 {
        let mut a_point: i8 = 0x01;
        let mut a_score = xins;
        let mut b_point: i8 = 0x02;
        let mut b_score = yins;

        if a_score >= b_score && zins > b_score {
            b_score = zins;
            b_point = 0x04;
        } else if a_score < b_score && zins > a_score {
            a_score = zins;
            a_point = 0x04;
        }

        let wins = 1.0 - in_sum;

        if wins > a_score || wins > b_score {
            let c = if b_score > a_score { b_point } else { a_point };

            if (c & 0x01) == 0 {
                xsv_ext0 = xsb - 1;
                xsv_ext1 = xsb;
                dx_ext0 = dx0 + 1.0;
                dx_ext1 = dx0;
            } else {
