                dz_ext0 = dz_ext1 = dz0 - 1.0;
            }
        } else {
            let c = a_point | b_point;

            if (c & 0x01) == 0 {
                xsv_ext0 = xsb;
                xsv_ext1 = xsb - 1;
                dx_ext0 = dx0 - 2.0 * (1.0 / 3.0);
