        }

        let dx3 = dx0 - 0.0 - (1.0 / 3.0);
        let dy3 = dy1;
        let dz3 = dz0 - 1.0 - (1.0 / 3.0);
        let attn3 = 2.0 - dx3 * dx3 - dy3 * dy3 - dz3 * dz3;
        if attn3 > 0.0 {
            attn3 *= attn3;
            value += attn3 * attn3 * extrapolate3(ctx, xsb, ysb, zsb + 1, dx3, dy3, dz3);
        }

        let dx4 = dx0 - 1.0 - 2.0 * (1.0 / 3.0);
        let dy4 = dy0 - 1.0 - 2.0 * (1.0 / 3.0);
        let dz4 = dz0 - 0.0 - 2.0 * (1.0 / 3.0);
        let attn4 = 2.0 - dx4 * dx4 - dy4 * dy4 - dz4 * dz4;
        if attn4 > 0.0 {
            attn4 *= attn4;
            value += attn4 * attn4 * extrapolate3(ctx, xsb + 1, ysb + 1, zsb, dx4, dy4, dz4);
        }
    }
    value
}

