pub fn open_simplex_noise(seed: i64, ctx: &mut Option<OsnContext>) -> i32 {
    let mut source: [i16; 256] = [0; 256];
    let mut perm: Vec<i16>;
    let mut perm_grad_index_3d: Vec<i16>;

    *ctx = Some(OsnContext {
        perm: Vec::new(),
        perm_grad_index_3d: Vec::new(),
    });

    if ctx.is_none() {
        return -12;
    }

    let mut ctx_ref = ctx.as_mut().unwrap();
    let rc = allocate_perm(ctx_ref, 256, 256);
    if rc != 0 {
        *ctx = None;
        return rc;
    }

    perm = ctx_ref.perm.clone();
    perm_grad_index_3d = ctx_ref.perm_grad_index_3d.clone();

    for i in 0..256 {
        source[i] = i as i16;
    }

    let mut seed = seed;
    seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
    seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
    seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);

    for i in (0..256).rev() {
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        let mut r = ((seed + 31) % (i + 1) as i64) as i32;
        if r < 0 {
            r += (i + 1) as i32;
        }
        perm[i] = source[r as usize];
        perm_grad_index_3d[i] = ((perm[i] % (GRADIENTS_3D.len() as i16 / 3)) * 3) as i16;
        source[r as usize] = source[i];
    }

    ctx_ref.perm = perm;
    ctx_ref.perm_grad_index_3d = perm_grad_index_3d;

    0
}

pub fn open_simplex_noise_init_perm(ctx: &mut OsnContext, p: &[i16], nelements: usize) -> i32 {
    let rc = allocate_perm(ctx, nelements, 256);
    if rc != 0 {
        return rc;
    }
    ctx.perm[..nelements].copy_from_slice(&p[..nelements]);
    for i in 0..256 {
        ctx.perm_grad_index_3d[i] = (ctx.perm[i] % (GRADIENTS_3D.len() as i16 / 3)) * 3;
    }
    0
}

pub fn km_vec4_normalize(p_out: &mut KmVec4, p_in: &KmVec4) -> &mut KmVec4 {
    if p_in.x == 0.0 && p_in.y == 0.0 && p_in.z == 0.0 && p_in.w == 0.0 {
        return km_vec4_assign(p_out, p_in);
    }
    let l = 1.0 / km_vec4_length(p_in);
    p_out.x = p_in.x * l;
    p_out.y = p_in.y * l;
    p_out.z = p_in.z * l;
    p_out.w = p_in.w * l;
    p_out
}

pub fn km_quaternion_length(p_in: &KmQuaternion) -> f32 {
    km_quaternion_length_sq(p_in).sqrt()
}

pub fn km_quaternion_multiply(p_out: &mut KmQuaternion, qu1: &KmQuaternion, qu2: &KmQuaternion) -> &mut KmQuaternion {
    let mut tmp1 = KmQuaternion { x: 0.0, y: 0.0, z: 0.0, w: 0.0 };
    let mut tmp2 = KmQuaternion { x: 0.0, y: 0.0, z: 0.0, w: 0.0 };
    km_quaternion_assign(&mut tmp1, qu1);
    km_quaternion_assign(&mut tmp2, qu2);
    let q1 = &tmp1;
    let q2 = &tmp2;
    p_out.x = q1.w * q2.x + q1.x * q2.w + q1.y * q2.z - q1.z * q2.y;
    p_out.y = q1.w * q2.y + q1.y * q2.w + q1.z * q2.x - q1.x * q2.z;
    p_out.z = q1.w * q2.z + q1.z * q2.w + q1.x * q2.y - q1.y * q2.x;
    p_out.w = q1.w * q2.w - q1.x * q2.x - q1.y * q2.y - q1.z * q2.z;
    p_out
}

pub fn km_mat4_rotation_quaternion(p_out: &mut KmMat4, p_q: &KmQuaternion) -> &mut KmMat4 {
    let xx = p_q.x * p_q.x;
    let xy = p_q.x * p_q.y;
    let xz = p_q.x * p_q.z;
    let xw = p_q.x * p_q.w;
    let yy = p_q.y * p_q.y;
    let yz = p_q.y * p_q.z;
    let yw = p_q.y * p_q.w;
    let zz = p_q.z * p_q.z;
    let zw = p_q.z * p_q.w;

    p_out.mat[0] = 1.0 - 2.0 * (yy + zz);
    p_out.mat[1] = 2.0 * (xy + zw);
    p_out.mat[2] = 2.0 * (xz - yw);
    p_out.mat[3] = 0.0;
    p_out.mat[4] = 2.0 * (xy - zw);
    p_out.mat[5] = 1.0 - 2.0 * (xx + zz);
    p_out.mat[6] = 2.0 * (yz + xw);
    p_out.mat[7] = 0.0;
    p_out.mat[8] = 2.0 * (xz + yw);
    p_out.mat[9] = 2.0 * (yz - xw);
    p_out.mat[10] = 1.0 - 2.0 * (xx + yy);
    p_out.mat[11] = 0.0;
    p_out.mat[12] = 0.0;
    p_out.mat[13] = 0.0;
    p_out.mat[14] = 0.0;
    p_out.mat[15] = 1.0;

    p_out
}

pub fn km_mat4_perspective_projection(
    p_out: &mut KmMat4,
    fov_y: f32,
    aspect: f32,
    z_near: f32,
    z_far: f32,
) -> Option<&KmMat4> {
    let r = km_degrees_to_radians(fov_y / 2.0);
    let delta_z = z_far - z_near;
    let s = r.sin();
    let mut cotangent = 0.0;

    if delta_z == 0.0 || s == 0.0 || aspect == 0.0 {
        return None;
    }

    cotangent = r.cos() / s;
    km_mat4_identity(p_out);
    p_out.mat[0] = cotangent / aspect;
    p_out.mat[5] = cotangent;
    p_out.mat[10] = -(z_far + z_near) / delta_z;
    p_out.mat[11] = -1.0;
    p_out.mat[14] = -2.0 * z_near * z_far / delta_z;
    p_out.mat[15] = 0.0;

    Some(p_out)
}

pub fn km_mat4_orthographic_projection(
    p_out: &mut KmMat4,
    left: f32,
    right: f32,
    bottom: f32,
    top: f32,
    near_val: f32,
    far_val: f32,
) -> &KmMat4 {
    let tx = -((right + left) / (right - left));
    let ty = -((top + bottom) / (top - bottom));
    let tz = -((far_val + near_val) / (far_val - near_val));
    km_mat4_identity(p_out);
    p_out.mat[0] = 2.0 / (right - left);
    p_out.mat[5] = 2.0 / (top - bottom);
    p_out.mat[10] = -2.0 / (far_val - near_val);
    p_out.mat[12] = tx;
    p_out.mat[13] = ty;
    p_out.mat[14] = tz;
    p_out
}

pub fn km_mat4_rotation_yaw_pitch_roll(p_out: &mut KmMat4, pitch: f32, yaw: f32, roll: f32) -> &KmMat4 {
    let mut yaw_matrix = KmMat4 { mat: [0.0; 16] };
    km_mat4_rotation_y(&mut yaw_matrix, yaw);

    let mut pitch_matrix = KmMat4 { mat: [0.0; 16] };
    km_mat4_rotation_x(&mut pitch_matrix, pitch);

    let mut roll_matrix = KmMat4 { mat: [0.0; 16] };
    km_mat4_rotation_z(&mut roll_matrix, roll);

    km_mat4_multiply(p_out, &pitch_matrix, &roll_matrix);
    km_mat4_multiply(p_out, &yaw_matrix, p_out);

    p_out
}

