}

pub fn km_mat3_inverse(p_out: &mut KmMat3, p_m: &KmMat3) -> Option<&KmMat3> {
    let determinate = km_mat3_determinant(p_m);
    if determinate == 0.0 {
        return None;
    }
    let det_inv = 1.0 / determinate;
    let mut adjugate = KmMat3 { mat: [0.0; 9] };
    km_mat3_adjugate(&mut adjugate, p_m);
    km_mat3_scalar_multiply(p_out, &adjugate, det_inv);
    Some(p_out)
}

pub fn km_mat3_assign_mat4(p_out: &mut KmMat3, p_in: &KmMat4) -> &mut KmMat3 {
    p_out.mat[0] = p_in.mat[0];
