    p_out.mat[2] = p_in.mat[2];
    p_out.mat[3] = p_in.mat[4];
    p_out.mat[4] = p_in.mat[5];
    p_out.mat[5] = p_in.mat[6];
    p_out.mat[6] = p_in.mat[8];
    p_out.mat[7] = p_in.mat[9];
    p_out.mat[8] = p_in.mat[10];
    p_out
}

pub fn km_mat3_rotation_quaternion(p_out: &mut KmMat3, p_in: &KmQuaternion) -> Option<&mut KmMat3> {
    if p_in.is_none() || p_out.is_none() {
        return None;
    }
    p_out.mat[0] = 1.0 - 2.0 * (p_in.y * p_in.y + p_in.z * p_in.z);
    p_out.mat[1] = 2.0 * (p_in.x * p_in.y - p_in.w * p_in.z);
    p_out.mat[2] = 2.0 * (p_in.x * p_in.z + p_in.w * p_in.y);
    p_out.mat[3] = 2.0 * (p_in.x * p_in.y + p_in.w * p_in.z);
    p_out.mat[4] = 1.0 - 2.0 * (p_in.x * p_in.x + p_in.z * p_in.z);
    p_out.mat[5] = 2.0 * (p_in.y * p_in.z - p_in.w * p_in.x);
    p_out.mat[6] = 2.0 * (p_in.x * p_in.z - p_in.w * p_in.y);
    p_out.mat[7] = 2.0 * (p_in.y * p_in.z + p_in.w * p_in.x);
    p_out.mat[8] = 1.0 - 2.0 * (p_in.x * p_in.x + p_in.y * p_in.y);
    Some(p_out)
}

