pub fn km_plane_get_intersection(
    p_out: &mut KmVec3,
    p1: &KmPlane,
    p2: &KmPlane,
    p3: &KmPlane,
) -> Option<&KmVec3> {
    let mut n1 = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
    let mut n2 = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
    let mut n3 = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
    let mut cross = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
    let mut r1 = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
    let mut r2 = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
    let mut r3 = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };

    km_vec3_fill(&mut n1, p1.a, p1.b, p1.c);
    km_vec3_fill(&mut n2, p2.a, p2.b, p2.c);
    km_vec3_fill(&mut n3, p3.a, p3.b, p3.c);

    km_vec3_cross(&mut cross, &n2, &n3);
    let denom = km_vec3_dot(&n1, &cross);

    if km_almost_equal(denom, 0.0) != 0 {
        return None;
    }

    km_vec3_cross(&mut r1, &n2, &n3);
    km_vec3_cross(&mut r2, &n3, &n1);
    km_vec3_cross(&mut r3, &n1, &n2);

    km_vec3_scale(&mut r1, &r1, -p1.d);
    km_vec3_scale(&mut r2, &r2, p2.d);
    km_vec3_scale(&mut r3, &r3, p3.d);

    km_vec3_subtract(p_out, &r1, &r2);
    km_vec3_subtract(p_out, p_out, &r3);
    km_vec3_scale(p_out, p_out, 1.0 / denom);

    Some(p_out)
}

pub fn km_vec3_reflect(p_out: &mut KmVec3, p_in: &KmVec3, normal: &KmVec3) -> &mut KmVec3 {
    let mut tmp = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
    km_vec3_scale(&mut tmp, normal, 2.0 * km_vec3_dot(p_in, normal));
    km_vec3_subtract(p_out, p_in, &tmp);
    p_out
}

