pub fn km_aabb3_initialize(
    p_box: &mut KmAABB3,
    centre: Option<&KmVec3>,
    width: f32,
    height: f32,
    depth: f32,
) -> Option<&mut KmAABB3> {
    if p_box.is_none() {
        return None;
    }

    let mut origin = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
    let point = centre.unwrap_or(&origin);
    km_vec3_zero(&mut origin);

    p_box.min.x = point.x - (width / 2.0);
    p_box.min.y = point.y - (height / 2.0);
    p_box.min.z = point.z - (depth / 2.0);
    p_box.max.x = point.x + (width / 2.0);
    p_box.max.y = point.y + (height / 2.0);
    p_box.max.z = point.z + (depth / 2.0);

    Some(p_box)
}

