        p_out.min.x = p_in.min.x;
        p_out.max.x = p_in.max.x;
    } else {
        p_out.min.x = p_in.max.x;
        p_out.max.x = p_in.min.x;
    }
    if p_in.min.y <= p_in.max.y {
        p_out.min.y = p_in.min.y;
        p_out.max.y = p_in.max.y;
    } else {
        p_out.min.y = p_in.max.y;
        p_out.max.y = p_in.min.y;
    }
    p_out
}

