pub fn heman_color_create_gradient(
    width: i32,
    num_colors: i32,
    cp_locations: &[i32],
    cp_values: &[HemanColor],
) -> HemanImage {
    assert!(width > 0 && num_colors >= 2, "width > 0 && num_colors >= 2");
    assert!(cp_locations[0] == 0, "cp_locations[0] == 0");
    assert!(
        cp_locations[(num_colors - 1) as usize] == width - 1,
        "cp_locations[num_colors - 1] == width - 1"
    );

    let mut f32colors = Vec::with_capacity((3 * num_colors) as usize);
    let inv = 1.0 / 255.0;

    for &rgb in cp_values {
        let r = ((rgb >> 16) as f32) * inv;
        let g = (((rgb >> 8) & 0xff) as f32) * inv;
        let b = ((rgb & 0xff) as f32) * inv;
        f32colors.push(r.powf(GAMMA));
        f32colors.push(g.powf(GAMMA));
        f32colors.push(b.powf(GAMMA));
    }

    let mut result = heman_image_create(width, 1, 3);
    let mut index0 = 0;
    let mut index1 = 1;
    let mut dst = &mut result.data[..];
    let invgamma = 1.0 / GAMMA;

    for x in 0..width {
        let loc0 = cp_locations[index0];
        let loc1 = cp_locations[index1];
        let t = if loc0 == loc1 {
            0.0
        } else {
            let t = (x - loc0) as f32 / (loc1 - loc0) as f32;
            if t >= 1.0 {
                index0 += 1;
                index1 = min(index1 + 1, num_colors - 1);
                continue;
            }
            t
        };

        let r0 = f32colors[(index0 * 3) as usize];
        let g0 = f32colors[(index0 * 3 + 1) as usize];
        let b0 = f32colors[(index0 * 3 + 2) as usize];
        let r1 = f32colors[(index1 * 3) as usize];
        let g1 = f32colors[(index1 * 3 + 1) as usize];
        let b1 = f32colors[(index1 * 3 + 2) as usize];
        let invt = 1.0 - t;
        let r = (r0 * invt) + (r1 * t);
        let g = (g0 * invt) + (g1 * t);
        let b = (b0 * invt) + (b1 * t);
        dst[0] = r.powf(invgamma);
        dst[1] = g.powf(invgamma);
        dst[2] = b.powf(invgamma);
        dst = &mut dst[3..];
    }

    result
}

