pub fn heman_points_from_grid(width: f32, height: f32, cellsize: f32, jitter: f32) -> HemanImage {
    let cols = (width / cellsize) as i32;
    let rows = (height / cellsize) as i32;
    let ncells = cols * rows;
    let mut result = heman_image_create(ncells, 1, 2);
    let rscale = 2.0 * jitter / 2147483647.0;

    let result_data = Arc::new(Mutex::new(&mut result.data));

    (0..rows).into_par_iter().for_each(|j| {
        let mut rng = rand::thread_rng();
        let mut dst = result_data.lock().unwrap();
        let y = cellsize * 0.5 + cellsize * j as f32;
        let mut x = cellsize * 0.5;
        for _ in 0..cols {
            let rx = rng.gen::<f32>() * rscale - jitter;
            let ry = rng.gen::<f32>() * rscale - jitter;
            dst.push(x + rx);
            dst.push(y + ry);
            x += cellsize;
        }
    });

    result
}

