            if i < 0 || i >= target.width || j < 0 || j >= target.height {
                continue;
            }
            if let Some(texel) = heman_image_texel(target, i, j) {
                for c in 0..target.nbands {
                    texel[c] = val;
                }
            }
        }
    }
}

pub fn heman_draw_colored_points(target: &mut HemanImage, pts: &HemanImage, colors: &[HemanColor]) {
    assert!(target.nbands == 3 || target.nbands == 4, "target->nbands must be 3 or 4");
    let src = &pts.data;
    let inv = 1.0 / 255.0;
    for k in 0..pts.width {
        let x = src[(k * pts.nbands) as usize];
        let y = src[(k * pts.nbands + 1) as usize];
        let i = (x * target.width as f32) as i32;
        let j = (y * target.height as f32) as i32;
        if i < 0 || i >= target.width || j < 0 || j >= target.height {
            continue;
        }
        if let Some(texel) = heman_image_texel(target, i, j) {
            let rgb = colors[k as usize];
            texel[0] = ((rgb >> 16) & 0xff) as f32 * inv;
            texel[1] = ((rgb >> 8) & 0xff) as f32 * inv;
            texel[2] = (rgb & 0xff) as f32 * inv;
            if target.nbands == 4 {
                texel[3] = (rgb >> 24) as f32 * inv;
            }
        }
    }
}

pub fn heman_draw_colored_circles(
    target: &mut HemanImage,
    pts: &HemanPoints,
    radius: i32,
    colors: &[HemanColor],
) {
    let fwidth = radius * 2 + 1;
    let radius2 = radius * radius;
    let src = &pts.data;
    let inv = 1.0 / 255.0;
    let w = target.width;
    let h = target.height;
    let mut src_index = 0;

    for k in 0..pts.width {
        let x = src[src_index];
        let y = src[src_index + 1];
        src_index += pts.nbands as usize;
        let ii = (x * w as f32) as i32 - radius;
        let jj = (y * h as f32) as i32 - radius;

        for kj in 0..fwidth {
            for ki in 0..fwidth {
                let i = ii + ki;
                let j = jj + kj;
                let r2 = ((i as f32 - x * w as f32).powi(2) + (j as f32 - y * h as f32).powi(2)) as i32;
                if r2 > radius2 {
                    continue;
                }
                if let Some(texel) = heman_image_texel(target, i, j) {
                    let rgb = colors[k as usize];
                    texel[0] = ((rgb >> 16) as f32) * inv;
                    texel[1] = (((rgb >> 8) & 0xff) as f32) * inv;
                    texel[2] = ((rgb & 0xff) as f32) * inv;
                }
            }
        }
    }
}

pub fn heman_draw_splats(target: &mut HemanImage, pts: &HemanImage, radius: i32, blend_mode: i32) {
    let fwidth = (radius * 2 + 1) as usize;
    let mut gaussian_splat = vec![0.0f32; fwidth * fwidth];
    generate_gaussian_splat(&mut gaussian_splat, fwidth);
    let src = &pts.data;
    let w = target.width;
    let h = target.height;
    let nbands = target.nbands;

    for i in 0..pts.width {
        let x = src[(i * 2) as usize];
        let y = src[(i * 2 + 1) as usize];
        let ii = (x * w as f32) as i32 - radius;
        let jj = (y * h as f32) as i32 - radius;

        for kj in 0..fwidth {
            for ki in 0..fwidth {
                let i = ii + ki as i32;
                let j = jj + kj as i32;
                if i < 0 || i >= w || j < 0 || j >= h {
                    continue;
                }
                if let Some(texel) = heman_image_texel(target, i, j) {
                    for c in 0..nbands {
                        texel[c as usize] += gaussian_splat[kj * fwidth + ki];
                    }
                }
            }
        }
    }
}

use std::fs::File;
use std::io::{self, Write};
use std::ptr;

pub fn heman_export_ply(img: &HemanImage, filename: &str) -> io::Result<()> {
    assert_eq!(img.nbands, 1, "img->nbands == 1");

    let mut fout = File::create(filename)?;
    let ncols = img.width - 1;
    let nrows = img.height - 1;
    let ncells = ncols * nrows;
    let nverts = img.width * img.height;

    writeln!(fout, "ply\nformat binary_little_endian 1.0\ncomment heman")?;
    writeln!(fout, "element vertex {}\nproperty float32 x\nproperty float32 y\nproperty float32 z", nverts)?;
    writeln!(fout, "element face {}\nproperty list int32 int32 vertex_indices\nend_header", ncells)?;

    let invw = 2.0 / img.width as f32;
    let invh = 2.0 / img.height as f32;
    let mut vert = [0.0f32; 3];

    for j in 0..img.height {
        for i in 0..img.width {
            vert[0] = -1.0 + i as f32 * invw;
            vert[1] = -1.0 + j as f32 * invh;
            if let Some(texel) = heman_image_texel(img, i, j) {
                vert[2] = texel[0];
            }
            fout.write_all(bytemuck::cast_slice(&vert))?;
        }
    }

    let mut face = [0i32; 5];
    face[0] = 4;

    for j in 0..nrows {
        let mut p = j * img.width;
        for i in 0..ncols {
            face[1] = p;
            face[2] = p + 1;
            face[3] = p + img.width + 1;
            face[4] = p + img.width;
            fout.write_all(bytemuck::cast_slice(&face))?;
            p += 1;
        }
    }

    Ok(())
}

