use std::cmp::{max, min};

pub fn heman_internal_draw_seeds(target: &mut HemanImage, pts: &HemanPoints, filterd: i32) {
    let radius = target.width / filterd;
    let fwidth = radius * 2 + 1;
    let src = &pts.data;
    let w = target.width;
    let h = target.height;
    let mut index = 0;

    for _ in 0..pts.width {
        let x = src[index];
        let y = src[index + 1];
        index += 2;
        let mut strength = DEFAULT_STRENGTH;
        if pts.nbands == 3 {
            strength = src[index];
            index += 1;
        }
        strength = SEALEVEL + strength * 0.1;
        let ix = (x * w as f32) as i32;
        let iy = (y * h as f32) as i32;
        let ii = ix - radius;
        let jj = iy - radius;

        for kj in 0..fwidth {
            for ki in 0..fwidth {
                let i = ii + ki;
                let j = jj + kj;
                if i < 0 || i >= w || j < 0 || j >= h {
                    continue;
                }
                if let Some(texel) = heman_image_texel(target, i, j) {
                    let d2 = (i - ix) * (i - ix) + (j - iy) * (j - iy);
                    let dist = 1.0 - (d2 as f32).sqrt() / radius as f32;
                    let new_value = strength * dist;
                    if texel[0] < new_value {
                        texel[0] = new_value;
                    }
                }
            }
        }
    }
}

