    pub width: i32,
    pub nbands: i32,
    pub data: Vec<f32>,
}

pub fn heman_image_sample(img: &HemanImage, u: f32, v: f32, result: &mut [f32]) {
    let x = (0.0f32).max((img.width - 1) as f32).min(img.width as f32 * u) as i32;
    let y = (0.0f32).max((img.height - 1) as f32).min(img.height as f32 * v) as i32;

    if let Some(data) = heman_image_texel(img, x, y) {
        for (b, res) in result.iter_mut().enumerate().take(img.nbands as usize) {
            *res = data[b];
        }
    }
}

pub fn heman_ops_laplacian(heightmap: &HemanImage) -> HemanImage {
    assert_eq!(heightmap.nbands, 1, "heightmap->nbands == 1");
    let width = heightmap.width;
    let height = heightmap.height;
    let result = heman_image_create(width, height, 1);
    let maxx = width - 1;
    let maxy = height - 1;

    let result_data = Arc::new(Mutex::new(result.data));

    (0..height).into_par_iter().for_each(|y| {
        let y1 = if y + 1 > maxy { maxy } else { y + 1 };
        let mut dst = vec![0.0; width];
        for x in 0..width {
            let x1 = if x + 1 > maxx { maxx } else { x + 1 };
            let p = heman_image_texel(heightmap, x, y).unwrap()[0];
            let px = heman_image_texel(heightmap, x1, y).unwrap()[0];
            let py = heman_image_texel(heightmap, x, y1).unwrap()[0];
            dst[x] = (p - px) * (p - px) + (p - py) * (p - py);
        }
        let mut result_data_lock = result_data.lock().unwrap();
        for x in 0..width {
            result_data_lock[y * width + x] = dst[x];
        }
    });

    HemanImage {
        width,
        height,
        nbands: 1,
        data: Arc::try_unwrap(result_data).unwrap().into_inner().unwrap(),
    }
}

pub fn copy_row(src: &HemanImage, dst: &mut HemanImage, dstx: i32, y: i32) {
    let width = src.width;
    if src.nbands == 1 {
        for x in 0..width {
            if let (Some(srcp), Some(dstp)) = (
                heman_image_texel(src, x, y),
                heman_image_texel(dst, dstx + x, y),
            ) {
                dstp[0] = srcp[0];
            }
        }
        return;
    }
    for x in 0..width {
        if let (Some(srcp), Some(dstp)) = (
            heman_image_texel(src, x, y),
            heman_image_texel(dst, dstx + x, y),
        ) {
            let nbands = src.nbands as usize;
            for i in 0..nbands {
                dstp[i] = srcp[i];
            }
        }
    }
}

use std::f32;
use std::cmp::Ordering;

pub fn heman_ops_stairstep(
    hmap: &mut HemanImage,
    nsteps: i32,
    mask: Option<&HemanImage>,
    mask_color: HemanColor,
    invert_mask: i32,
    offset: f32,
) -> &mut HemanImage {
    assert_eq!(hmap.nbands, 1, "hmap->nbands must be 1");
    if let Some(mask) = mask {
        assert_eq!(mask.nbands, 3, "mask->nbands must be 3 if mask is provided");
    }

    let size = (hmap.height * hmap.width) as usize;
    let src = &mut hmap.data;
    let mut minv = f32::INFINITY;
    let mut maxv = f32::NEG_INFINITY;

    for i in 0..size {
        if mask.is_none() || match_pixel(mask.unwrap(), mask_color, invert_mask, i) != 0 {
            minv = minv.min(src[i]);
            maxv = maxv.max(src[i]);
        }
    }

    let range = maxv - minv;
    for i in 0..size {
        let mut e = src[i];
        if mask.is_none() || match_pixel(mask.unwrap(), mask_color, invert_mask, i) != 0 {
            e = (e - minv) / range;
            e = (e * nsteps as f32).floor() / nsteps as f32;
            e = e * range + minv;
        }
        src[i] = e + offset;
    }

    hmap
}

