pub fn heman_ops_percentiles(
    hmap: &mut HemanImage,
    nsteps: usize,
    mask: Option<&HemanImage>,
    mask_color: HemanColor,
    invert_mask: i32,
    offset: f32,
) -> &mut HemanImage {
    assert!(hmap.nbands == 1, "hmap->nbands == 1");
    assert!(mask.is_none() || mask.unwrap().nbands == 3, "!mask || mask->nbands == 3");

    let size = (hmap.height * hmap.width) as usize;
    let src = &mut hmap.data;
    let mut minv = 1000.0;
    let mut maxv = -1000.0;
    let mut npixels = 0;

    for i in 0..size {
        if mask.is_none() || match_pixel(mask.unwrap(), mask_color, invert_mask, i) != 0 {
            minv = minv.min(src[i]);
            maxv = maxv.max(src[i]);
            npixels += 1;
        }
    }

    let mut vals = Vec::with_capacity(npixels);
    npixels = 0;
    for i in 0..size {
        if mask.is_none() || match_pixel(mask.unwrap(), mask_color, invert_mask, i) != 0 {
            vals.push(src[i]);
            npixels += 1;
        }
    }

    let mut percentiles = Vec::with_capacity(nsteps);
    for tier in 0..nsteps {
        let height = qselect(&mut vals, npixels, tier * npixels / nsteps);
        percentiles.push(height);
    }

    for i in 0..size {
        let mut e = src[i];
        if mask.is_none() || match_pixel(mask.unwrap(), mask_color, invert_mask, i) != 0 {
            for tier in (0..nsteps).rev() {
                if e > percentiles[tier] {
                    e = percentiles[tier];
                    break;
                }
            }
        }
        src[i] = e + offset;
    }

    hmap
}

