pub fn heman_distance_create_sdf(src: &HemanImage) -> HemanImage {
    assert!(src.nbands == 1, "Distance field input must have only 1 band.");

    let mut positive = heman_image_create(src.width, src.height, 1);
    let mut negative = heman_image_create(src.width, src.height, 1);
    let size = src.height * src.width;

    let pptr = &mut positive.data;
    let nptr = &mut negative.data;
    let sptr = &src.data;

    for i in 0..size {
        pptr[i] = if sptr[i] != 0.0 { INF } else { 0.0 };
        nptr[i] = if sptr[i] != 0.0 { 0.0 } else { INF };
    }

    transform_to_distance(&mut positive);
    transform_to_distance(&mut negative);

    let inv = 1.0 / src.width as f32;

    for i in 0..size {
        pptr[i] = (pptr[i].sqrt() - nptr[i].sqrt()) * inv;
    }

    heman_image_destroy(negative);
    positive
}

pub fn heman_distance_create_df(src: &HemanImage) -> HemanImage {
    assert_eq!(src.nbands, 1, "Distance field input must have only 1 band.");

    let mut positive = heman_image_create(src.width, src.height, 1);
    let size = (src.height * src.width) as usize;
    let pptr = &mut positive.data;
    let sptr = &src.data;

    for i in 0..size {
