    }

    transform_to_distance(&mut positive);

    let inv = 1.0 / src.width as f32;
    for i in 0..size {
        pptr[i] = pptr[i].sqrt() * inv;
    }

    positive
}

use std::sync::Arc;
use std::sync::Mutex;
use rayon::prelude::*;

pub fn heman_generate_planet_heightmap(width: i32, height: i32, seed: i64) -> HemanImage {
    let mut ctx: Option<OsnContext> = None;
    open_simplex_noise(seed, &mut ctx);
    let ctx = Arc::new(Mutex::new(ctx.unwrap()));
    let mut result = heman_image_create(width, height, 1);
    let scalex = 2.0 * PI / width as f32;
    let scaley = PI / height as f32;
    let invh = 1.0 / height as f32;

    result.data.par_chunks_mut(width as usize).enumerate().for_each(|(y, dst)| {
        let mut p = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
        let mut v = y as f32 * invh;
        let s = 0.95;
        let antarctic_influence = (10.0 * (v - s) / s).max(-0.5);
        v = (v - 0.5).abs();
        v = 1.5 * (0.5 - v);
        let equatorial_influence = v * v;
        v = y as f32 * scaley;
        for x in 0..width {
            let u = x as f32 * scalex;
            let mut freq = 1.0;
            let mut amp = 1.0;
            let mut h = antarctic_influence + equatorial_influence;
            for _ in 0..6 {
                sphere(u, v, freq, &mut p);
                h += amp * open_simplex_noise3(&ctx.lock().unwrap(), p.x as f64, p.y as f64, p.z as f64) as f32;
                amp *= 0.5;
                freq *= 2.0;
            }
            dst[x as usize] = h;
        }
    });

    open_simplex_noise_free(Some(Box::new(ctx.lock().unwrap().clone())));
    result
}

