    let ctx = Arc::new(ctx.unwrap());

    (0..height).into_par_iter().for_each(|y| {
        let v = y as f32 * invh;
        let mut dst = data.lock().unwrap();
        let dst_slice = &mut dst[y as usize * width as usize..(y as usize + 1) * width as usize];
        for x in 0..width {
            let u = x as f32 * invw;
            dst_slice[x as usize] = ampls[0] * open_simplex_noise2(&ctx, u * freqs[0], v * freqs[0])
                + ampls[1] * open_simplex_noise2(&ctx, u * freqs[1], v * freqs[1])
                + ampls[2] * open_simplex_noise2(&ctx, u * freqs[2], v * freqs[2]);
        }
    });

    open_simplex_noise_free(Some(Box::new(ctx)));
    img
}

pub fn heman_ops_emboss(img: &HemanImage, mode: i32) -> HemanImage {
    let seed = 1;
    let octaves = 4;
    let mut ctx: Option<OsnContext> = None;
    open_simplex_noise(seed, &mut ctx);
    let ctx = Arc::new(Mutex::new(ctx.unwrap()));

    let width = img.width;
    let height = img.height;
    assert_eq!(img.nbands, 1, "img->nbands == 1");

    let mut result = heman_image_create(width, height, 1);
    let invw = 1.0 / width as f32;
    let invh = 1.0 / height as f32;
    let inv = invw.min(invh);
    let gain = 0.6;
    let lacunarity = 2.0;
    let land_amplitude = 0.0005;
    let land_frequency = 256.0;
    let ocean_amplitude = 0.5;
    let ocean_frequency = 1.0;

    (0..height).into_par_iter().for_each(|y| {
        let mut dst = &mut result.data[(y * width) as usize..((y + 1) * width) as usize];
        for x in 0..width {
            if let Some(texel) = heman_image_texel(img, x, y) {
                let mut z = texel[0];
                if z > 0.0 && mode == 1 {
                    let mut s = x as f32 * inv;
                    let mut t = y as f32 * inv;
                    let mut a = land_amplitude;
                    let mut f = land_frequency;
                    for _ in 0..octaves {
                        z += a * open_simplex_noise2(&ctx.lock().unwrap(), s * f, t * f);
                        a *= gain;
                        f *= lacunarity;
                    }
                } else if z <= 0.0 && mode == -1 {
                    z = z.max(-0.1);
                    let soften = z.abs();
                    let mut s = x as f32 * inv;
                    let mut t = y as f32 * inv;
                    let mut a = ocean_amplitude;
                    let mut f = ocean_frequency;
                    for _ in 0..octaves {
                        z += soften * (a * open_simplex_noise2(&ctx.lock().unwrap(), s * f, t * f));
                        a *= gain;
                        f *= lacunarity;
                    }
                }
                dst[x as usize] = z;
            }
        }
    });

    open_simplex_noise_free(Some(Box::new(ctx.lock().unwrap().clone())));
    result
}

pub fn heman_ops_warp_core(
    img: &HemanImage,
    secondary: Option<&mut HemanImage>,
    seed: i64,
    octaves: i32,
) -> HemanImage {
    let mut ctx: Option<OsnContext> = None;
    open_simplex_noise(seed, &mut ctx);
    let ctx = ctx.expect("Failed to create noise context");

    let width = img.width;
    let height = img.height;
    let nbands = img.nbands;
    let mut result = heman_image_create(width, height, nbands);
    let mut result2 = secondary.map(|sec| heman_image_create(width, height, sec.nbands));

    let invw = 1.0 / width as f32;
    let invh = 1.0 / height as f32;
    let inv = invw.min(invh);
    let aspect = width as f32 / height as f32;
    let gain = 0.6;
    let lacunarity = 2.0;
    let initial_amplitude = 0.05;
    let initial_frequency = 8.0;

    let result_data = Arc::new(Mutex::new(result.data.clone()));

    (0..height).into_par_iter().for_each(|y| {
        let mut dst = result_data.lock().unwrap();
        let dst_offset = y * width * nbands;
        for x in 0..width {
            let mut a = initial_amplitude;
            let mut f = initial_frequency;
            let mut src: &[f32] = &[];

            if nbands == 4 {
                if let Some(texel) = heman_image_texel(img, x, y) {
                    src = texel;
                    let elev = 1.0 - src[3];
                    a *= elev.powi(4);
                }
            }

            let s = x as f32 * inv;
            let t = y as f32 * inv;
            let mut u = x as f32 * invw;
            let mut v = y as f32 * invh;

            for _ in 0..octaves {
                u += a * open_simplex_noise2(&ctx, s * f, t * f);
                v += aspect * a * open_simplex_noise2(&ctx, s * f + 0.5, t * f);
                a *= gain;
                f *= lacunarity;
            }

            let i = cmp::max(0, cmp::min((u * width as f32) as i32, width - 1));
            let j = cmp::max(0, cmp::min((v * height as f32) as i32, height - 1));

            if let Some(texel) = heman_image_texel(img, i, j) {
                src = texel;
            }

            for n in 0..nbands {
                dst[dst_offset + x * nbands + n] = src[n];
            }

            if let Some(sec) = secondary {
                if let Some(texel) = heman_image_texel(sec, x, y) {
                    if let Some(dst2) = heman_image_texel(result2.as_mut().unwrap(), i, j) {
                        for n in 0..sec.nbands {
                            dst2[n] = texel[n];
                        }
                    }
                }
            }
        }
    });

    open_simplex_noise_free(Some(Box::new(ctx)));

    if let Some(sec) = secondary {
        if let Some(res2) = result2 {
            sec.data = res2.data;
        }
    }

    result
}

pub fn km_vec4_scale(p_out: &mut KmVec4, p_in: &KmVec4, s: f32) -> &mut KmVec4 {
    km_vec4_normalize(p_out, p_in);
    p_out.x *= s;
    p_out.y *= s;
    p_out.z *= s;
    p_out.w *= s;
    p_out
}

pub fn km_quaternion_inverse(p_out: &mut KmQuaternion, p_in: &KmQuaternion) -> &KmQuaternion {
    let l = km_quaternion_length(p_in);
    if l.abs() < 0.0001 {
        p_out.x = 0.0;
        p_out.y = 0.0;
        p_out.z = 0.0;
        p_out.w = 0.0;
        return p_out;
    }
    p_out.x = -p_in.x;
    p_out.y = -p_in.y;
    p_out.z = -p_in.z;
    p_out.w = p_in.w;
    p_out
}

pub fn km_quaternion_normalize(p_out: &mut KmQuaternion, p_in: &KmQuaternion) -> &KmQuaternion {
    let length = km_quaternion_length(p_in);
    if length.abs() < 0.0001 {
        p_out.x = 0.0;
        p_out.y = 0.0;
        p_out.z = 0.0;
        p_out.w = 0.0;
        return p_out;
    }
    km_quaternion_fill(p_out, p_out.x / length, p_out.y / length, p_out.z / length, p_out.w / length);
    p_out
}

pub fn km_aabb3_contains_aabb(container: &KmAABB3, to_check: &KmAABB3) -> u32 {
    let mut corners = [KmVec3 { x: 0.0, y: 0.0, z: 0.0 }; 8];
    let mut result: u32 = 2;
    let mut found: bool = false;

    km_vec3_fill(&mut corners[0], to_check.min.x, to_check.min.y, to_check.min.z);
    km_vec3_fill(&mut corners[1], to_check.max.x, to_check.min.y, to_check.min.z);
    km_vec3_fill(&mut corners[2], to_check.max.x, to_check.max.y, to_check.min.z);
    km_vec3_fill(&mut corners[3], to_check.min.x, to_check.max.y, to_check.min.z);
    km_vec3_fill(&mut corners[4], to_check.min.x, to_check.min.y, to_check.max.z);
    km_vec3_fill(&mut corners[5], to_check.max.x, to_check.min.y, to_check.max.z);
    km_vec3_fill(&mut corners[6], to_check.max.x, to_check.max.y, to_check.max.z);
    km_vec3_fill(&mut corners[7], to_check.min.x, to_check.max.y, to_check.max.z);

    for i in 0..8 {
        if !km_aabb3_contains_point(container, &corners[i]) {
            result = 1;
            if found {
                return result;
            }
        } else {
            found = true;
        }
    }

    if !found {
        result = 0;
    }

    result
}

pub fn km_vec3_project_on_to_plane(p_out: &mut KmVec3, point: &KmVec3, plane: &KmPlane) -> &mut KmVec3 {
    let mut ray = KmRay3 {
        start: KmVec3 { x: 0.0, y: 0.0, z: 0.0 },
        dir: KmVec3 { x: 0.0, y: 0.0, z: 0.0 },
    };
    km_vec3_assign(&mut ray.start, point);
    ray.dir.x = -plane.a;
    ray.dir.y = -plane.b;
    ray.dir.z = -plane.c;
    km_ray3_intersect_plane(p_out, &ray, plane);
    p_out
}

pub fn km_aabb3_expand_to_contain(p_out: &mut KmAABB3, p_in: &KmAABB3, other: &KmAABB3) -> &mut KmAABB3 {
    let mut result = KmAABB3 {
        min: KmVec3 {
            x: if p_in.min.x < other.min.x { p_in.min.x } else { other.min.x },
            y: if p_in.min.y < other.min.y { p_in.min.y } else { other.min.y },
            z: if p_in.min.z < other.min.z { p_in.min.z } else { other.min.z },
        },
        max: KmVec3 {
            x: if p_in.max.x > other.max.x { p_in.max.x } else { other.max.x },
            y: if p_in.max.y > other.max.y { p_in.max.y } else { other.max.y },
            z: if p_in.max.z > other.max.z { p_in.max.z } else { other.max.z },
        },
    };
    km_aabb3_assign(p_out, &result);
    p_out
}

use std::sync::Arc;
use std::sync::Mutex;
use rayon::prelude::*;

pub fn heman_lighting_compute_normals(heightmap: &HemanImage) -> HemanImage {
    assert_eq!(heightmap.nbands, 1, "heightmap->nbands must be 1");
    let width = heightmap.width;
    let height = heightmap.height;
    let result = heman_image_create(width, height, 3);
    let invh = 1.0 / height as f32;
    let invw = 1.0 / width as f32;
    let maxx = width - 1;
    let maxy = height - 1;
    let normals = Arc::new(Mutex::new(result.data));

    (0..height).into_par_iter().for_each(|y| {
        let v = y as f32 * invh;
        let y1 = if y + 1 > maxy { maxy } else { y + 1 };
        let mut p = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
        let mut px = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
        let mut py = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
        let mut n = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };

        for x in 0..width {
            let u = x as f32 * invw;
            let x1 = if x + 1 > maxx { maxx } else { x + 1 };
            p.x = u;
            p.y = v;
            p.z = *heman_image_texel(heightmap, x, y).unwrap();
            px.x = u + invw;
            px.y = v;
            px.z = *heman_image_texel(heightmap, x1, y).unwrap();
            py.x = u;
            py.y = v + invh;
            py.z = *heman_image_texel(heightmap, x, y1).unwrap();
            km_vec3_subtract(&mut px, &px, &p);
            km_vec3_subtract(&mut py, &py, &p);
            km_vec3_cross(&mut n, &px, &py);
            km_vec3_normalize(&mut n, &n);
            n.y *= -1.0;

            let mut normals_lock = normals.lock().unwrap();
            let index = (y * width + x) * 3;
            normals_lock[index] = n.x;
            normals_lock[index + 1] = n.y;
            normals_lock[index + 2] = n.z;
        }
    });

    result
}

