pub fn km_plane_normalize(p_out: &mut KmPlane, p_p: &KmPlane) -> &mut KmPlane {
    let mut n = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
    let mut l = 0.0;
    if p_p.a == 0.0 && p_p.b == 0.0 && p_p.c == 0.0 {
        p_out.a = p_p.a;
        p_out.b = p_p.b;
        p_out.c = p_p.c;
        p_out.d = p_p.d;
        return p_out;
    }
    n.x = p_p.a;
    n.y = p_p.b;
    n.z = p_p.c;
    l = 1.0 / km_vec3_length(&n);
    km_vec3_normalize(&mut n, &n);
    p_out.a = n.x;
    p_out.b = n.y;
    p_out.c = n.z;
    p_out.d = p_p.d * l;
    p_out
}

use std::f32::EPSILON;

pub fn km_plane_intersect_line(
    p_out: &mut KmVec3,
    p_p: &KmPlane,
    p_v1: &KmVec3,
    p_v2: &KmVec3,
) -> Option<&KmVec3> {
    let mut d = KmVec3 { x: 0.0, y: 0.0, z: 0.0 };
    km_vec3_subtract(&mut d, p_v2, p_v1);

    let mut n = KmVec3 {
        x: p_p.a,
        y: p_p.b,
        z: p_p.c,
    };
    km_vec3_normalize(&mut n, &n);

    let nt = -(n.x * p_v1.x + n.y * p_v1.y + n.z * p_v1.z + p_p.d);
    let dt = n.x * d.x + n.y * d.y + n.z * d.z;

    if dt.abs() < 0.0001 {
        return None;
    }

    let t = nt / dt;
    p_out.x = p_v1.x + d.x * t;
    p_out.y = p_v1.y + d.y * t;
    p_out.z = p_v1.z + d.z * t;

    Some(p_out)
}

pub fn km_quaternion_to_axis_angle(p_in: &KmQuaternion, p_axis: &mut KmVec3, p_angle: &mut f32) {
    let temp_angle = p_in.w.acos();
    let scale = (km_sqr(p_in.x) + km_sqr(p_in.y) + km_sqr(p_in.z)).sqrt();

    if (scale > -0.0001 && scale < 0.0001) || (scale < 2.0 * PI + 0.0001 && scale > 2.0 * PI - 0.0001) {
        *p_angle = 0.0;
        p_axis.x = 0.0;
        p_axis.y = 0.0;
        p_axis.z = 1.0;
    } else {
        *p_angle = temp_angle * 2.0;
        p_axis.x = p_in.x / scale;
        p_axis.y = p_in.y / scale;
        p_axis.z = p_in.z / scale;
        km_vec3_normalize(p_axis, p_axis);
    }
}

pub fn km_aabb2_contains_aabb(container: &KmAABB2, to_check: &KmAABB2) -> u32 {
    let mut corners = [KmVec2 { x: 0.0, y: 0.0 }; 4];
    km_vec2_fill(&mut corners[0], to_check.min.x, to_check.min.y);
    km_vec2_fill(&mut corners[1], to_check.max.x, to_check.min.y);
    km_vec2_fill(&mut corners[2], to_check.max.x, to_check.max.y);
    km_vec2_fill(&mut corners[3], to_check.min.x, to_check.max.y);

    let n_contains = km_aabb2_contains_point(container, &corners[0])
        + km_aabb2_contains_point(container, &corners[1])
        + km_aabb2_contains_point(container, &corners[2])
        + km_aabb2_contains_point(container, &corners[3]);

    if n_contains == 0 {
        0
    } else if n_contains < 4 {
        1
    } else {
        2
    }
}

pub fn km_ray2_intersect_line_segment(
    ray: &KmRay2,
    p1: &KmVec2,
    p2: &KmVec2,
    intersection: &mut KmVec2,
) -> u8 {
    let mut ua: f32 = 0.0;
    let mut ub: f32 = 0.0;
    let mut pt = KmVec2 { x: 0.0, y: 0.0 };
    let mut other_segment = KmRay2 {
        start: KmVec2 { x: 0.0, y: 0.0 },
        dir: KmVec2 { x: 0.0, y: 0.0 },
    };

    km_ray2_fill_with_endpoints(&mut other_segment, p1, p2);

    if km_line2_with_line_intersection(
        &ray.start,
        &ray.dir,
        &other_segment.start,
        &other_segment.dir,
        Some(&mut ua),
        Some(&mut ub),
        Some(&mut pt),
    ) != 0
        && (0.0 <= ua)
        && (0.0 <= ub)
        && (ub <= 1.0)
    {
        intersection.x = pt.x;
        intersection.y = pt.y;
        return 1;
    }
    0
}

pub fn km_aabb2_scale_with_pivot(
