pub fn heman_points_from_poisson(width: f32, height: f32, radius: f32) -> HemanPoints {
    let maxattempts = 30;
    let rscale = 1.0 / (2147483647_u32.wrapping_mul(2) as f32 + 1.0);
    let mut seed = 0_u32;
    let rvec = KmVec2 { x: radius, y: radius };
