    let nrows = f32::ceil(height * invcell) as i32;
    let maxcol = ncols - 1;
    let maxrow = nrows - 1;
    let ncells = ncols * nrows;
    let mut grid = vec![-1; ncells as usize];
    let mut actives = vec![-1; ncells as usize];
    let mut nactives = 0;
    let mut result = HemanPoints {
        width: ncells,
        height: 1,
        nbands: 2,
        data: vec![0.0; (ncells * 2) as usize],
    };
    let samples = unsafe { std::slice::from_raw_parts_mut(result.data.as_mut_ptr() as *mut KmVec2, ncells as usize) };
    let mut nsamples = 0;
    let mut pt = KmVec2 {
        x: width * randhash(seed) as f32 * rscale,
        y: height * randhash(seed.wrapping_add(1)) as f32 * rscale,
    };
    seed = seed.wrapping_add(2);
    grid[(pt.x * invcell) as usize + ncols as usize * (pt.y * invcell) as usize] = nsamples;
    actives[nactives] = nsamples;
    nactives += 1;
    samples[nsamples] = pt;
    nsamples += 1;

    while nsamples < ncells {
        let aindex = min(randhashf(seed, 0.0, nactives as f32) as i32, nactives - 1);
        seed = seed.wrapping_add(1);
        let sindex = actives[aindex as usize];
        let mut found = false;
        let mut j = KmVec2 { x: 0.0, y: 0.0 };
        let mut minj = KmVec2 { x: 0.0, y: 0.0 };
        let mut maxj = KmVec2 { x: 0.0, y: 0.0 };
        let mut delta = KmVec2 { x: 0.0, y: 0.0 };

        for _ in 0..maxattempts {
            pt = sample_annulus(radius, samples[sindex as usize], &mut seed);
            if pt.x < 0.0 || pt.x >= width || pt.y < 0.0 || pt.y >= height {
                continue;
            }
            minj = pt;
            maxj = pt;
            km_vec2_add(&mut maxj, &maxj, &rvec);
            km_vec2_subtract(&mut minj, &minj, &rvec);
            km_vec2_scale(&mut minj, &minj, invcell);
            km_vec2_scale(&mut maxj, &maxj, invcell);
            minj.x = max(0, min(maxcol, minj.x as i32)) as f32;
            maxj.x = max(0, min(maxcol, maxj.x as i32)) as f32;
            minj.y = max(0, min(maxrow, minj.y as i32)) as f32;
            maxj.y = max(0, min(maxrow, maxj.y as i32)) as f32;

            let mut reject = false;
            for j_y in minj.y as i32..=maxj.y as i32 {
                for j_x in minj.x as i32..=maxj.x as i32 {
                    let entry = grid[j_y as usize * ncols as usize + j_x as usize];
                    if entry > -1 && entry != sindex {
                        km_vec2_subtract(&mut delta, &samples[entry as usize], &pt);
                        if km_vec2_length_sq(&delta) < r2 {
                            reject = true;
                            break;
                        }
                    }
                }
                if reject {
                    break;
                }
            }
            if !reject {
                found = true;
                break;
            }
        }

        if found {
            grid[(pt.x * invcell) as usize + ncols as usize * (pt.y * invcell) as usize] = nsamples;
            actives[nactives] = nsamples;
            nactives += 1;
            samples[nsamples] = pt;
            nsamples += 1;
        } else {
            nactives -= 1;
            if nactives <= 0 {
                break;
            }
            actives[aindex as usize] = actives[nactives as usize];
        }
    }

    result.width = nsamples;
    result
}

