pub fn km_aabb2_expand_to_contain(p_out: &mut KmAABB2, p_in: &KmAABB2, other: &KmAABB2) -> &mut KmAABB2 {
    let mut result = KmAABB2 {
        min: KmVec2 { x: 0.0, y: 0.0 },
        max: KmVec2 { x: 0.0, y: 0.0 },
    };

    result.min.x = if p_in.min.x < other.min.x { p_in.min.x } else { other.min.x };
