pub fn calculate_line_normal(p1: KmVec2, p2: KmVec2, other_point: KmVec2, normal_out: &mut KmVec2) {
    let mut edge = KmVec2 { x: 0.0, y: 0.0 };
    let mut other_edge = KmVec2 { x: 0.0, y: 0.0 };

    km_vec2_subtract(&mut edge, &p2, &p1);
    km_vec2_subtract(&mut other_edge, &other_point, &p1);

    km_vec2_normalize(&mut edge, &edge);
    km_vec2_normalize(&mut other_edge, &other_edge);

    let mut n = KmVec2 { x: edge.y, y: -edge.x };
    let d = km_vec2_dot(&n, &other_edge);

    if d > 0.0 {
        n.x = -n.x;
        n.y = -n.y;
    }

    normal_out.x = n.x;
    normal_out.y = n.y;
    km_vec2_normalize(normal_out, normal_out);
}

pub fn km_vec2_degrees_between(v1: &KmVec2, v2: &KmVec2) -> f32 {
    if km_vec2_are_equal(v1, v2) {
        return 0.0;
    }
    let mut t1 = KmVec2 { x: 0.0, y: 0.0 };
    let mut t2 = KmVec2 { x: 0.0, y: 0.0 };
    km_vec2_normalize(&mut t1, v1);
    km_vec2_normalize(&mut t2, v2);
    let cross = km_vec2_cross(&t1, &t2);
    let mut dot = km_vec2_dot(&t1, &t2);
    if dot > 1.0 {
        dot = 1.0;
    }
    if dot < -1.0 {
        dot = -1.0;
    }
    km_radians_to_degrees(cross.atan2(dot))
}

pub fn heman_ops_sobel(img: &HemanImage, rgb: HemanColor) -> HemanImage {
    let width = img.width;
    let height = img.height;
    assert_eq!(img.nbands, 3, "img->nbands must be 3");

    let result = heman_image_create(width, height, 3);
    let gray = heman_color_to_grayscale(img);
    let inv = 1.0 / 255.0;
    let edge_rgb = KmVec3 {
        x: ((rgb >> 16) as f32) * inv,
        y: (((rgb >> 8) & 0xff) as f32) * inv,
        z: ((rgb & 0xff) as f32) * inv,
    };

    let result_data = Arc::new(result.data);
    let gray_data = Arc::new(gray.data);

    (0..height).into_par_iter().for_each(|y| {
        let dst = &mut result_data[y * width * 3..(y + 1) * width * 3];
        let src = &img.data[y * width * 3..(y + 1) * width * 3];

        for x in 0..width {
            let xm1 = if x > 0 { x - 1 } else { 0 };
            let xp1 = if x < width - 1 { x + 1 } else { width - 1 };
            let ym1 = if y > 0 { y - 1 } else { 0 };
            let yp1 = if y < height - 1 { y + 1 } else { height - 1 };

            let t00 = *heman_image_texel(&gray, xm1, ym1).unwrap_or(&0.0);
            let t10 = *heman_image_texel(&gray, x, ym1).unwrap_or(&0.0);
            let t20 = *heman_image_texel(&gray, xp1, ym1).unwrap_or(&0.0);
            let t01 = *heman_image_texel(&gray, xm1, y).unwrap_or(&0.0);
            let t21 = *heman_image_texel(&gray, xp1, y).unwrap_or(&0.0);
            let t02 = *heman_image_texel(&gray, xm1, yp1).unwrap_or(&0.0);
            let t12 = *heman_image_texel(&gray, x, yp1).unwrap_or(&0.0);
            let t22 = *heman_image_texel(&gray, xp1, yp1).unwrap_or(&0.0);

            let gx = t00 + 2.0 * t01 + t02 - t20 - 2.0 * t21 - t22;
            let gy = t00 + 2.0 * t10 + t20 - t02 - 2.0 * t12 - t22;
            let is_edge = (gx * gx + gy * gy) > 1e-5;

            let mut dst_vec = KmVec3 {
                x: src[x * 3],
                y: src[x * 3 + 1],
                z: src[x * 3 + 2],
            };

            km_vec3_lerp(&mut dst_vec, &dst_vec, &edge_rgb, is_edge as f32);

            dst[x * 3] = dst_vec.x;
            dst[x * 3 + 1] = dst_vec.y;
            dst[x * 3 + 2] = dst_vec.z;
        }
    });

    heman_image_destroy(gray);
    result
}

pub fn heman_color_from_cpcf(cfield: &HemanImage, texture: Option<&HemanImage>) -> HemanImage {
    if texture.is_none() {
        return heman_internal_rg(cfield);
    }

    let texture = texture.unwrap();

    assert_eq!(cfield.nbands, 2, "cfield->nbands must be 2");
    assert!(texture.nbands == 3 || texture.nbands == 4, "texture->nbands must be 3 or 4");
    assert_eq!(cfield.width, texture.width, "cfield->width must equal texture->width");
    assert_eq!(cfield.height, texture.height, "cfield->height must equal texture->height");

    let w = cfield.width;
    let h = cfield.height;
    let mut target = heman_image_create(w, h, texture.nbands);
    let dst = &mut target.data;
    let src = &cfield.data;
    let size = (w * h) as usize;

    for i in 0..size {
        let u = src[i * 2];
        let v = src[i * 2 + 1];
        if let Some(texel) = heman_image_texel(texture, u as i32, v as i32) {
            for c in 0..texture.nbands as usize {
                dst[i * texture.nbands as usize + c] = texel[c];
            }
        }
    }

    target
}

pub fn heman_distance_create_cpcf(src: &HemanImage) -> HemanImage {
    let mut negative = heman_image_create(src.width, src.height, 1);
    let size = src.height * src.width;
    let nptr = &mut negative.data;
    let sptr = &src.data;
    for i in 0..size {
        let mut val = 0.0;
        for b in 0..src.nbands {
            val += sptr[i * src.nbands as usize + b as usize];
        }
        nptr[i] = if val != 0.0 { 0.0 } else { INF };
    }
    let mut coordfield = heman_distance_identity_cpcf(src.width, src.height);
    transform_to_coordfield(&mut negative, &mut coordfield);
    heman_image_destroy(negative);
    coordfield
}

use std::ptr;

pub fn heman_draw_contour_from_points(
    target: &mut HemanImage,
    coords: &HemanPoints,
    rgb: HemanColor,
    mind: f32,
    maxd: f32,
    filterd: i32,
) {
    assert!(target.nbands == 3 || target.nbands == 4, "target->nbands == 3 || target->nbands == 4");

    let width = target.width;
    let height = target.height;
    let mut seed = heman_image_create(width, height, 1);
    heman_image_clear(&mut seed, 0.0);
    heman_internal_draw_seeds(&mut seed, coords, filterd);

    let inv = 1.0 / 255.0;
    let r = ((rgb >> 16) & 0xff) as f32 * inv;
    let g = ((rgb >> 8) & 0xff) as f32 * inv;
    let b = (rgb & 0xff) as f32 * inv;
    let mut a = 1.0;
    if target.nbands == 4 {
        a = (rgb >> 24) as f32 * inv;
    }

    for y in 0..height {
        let mut dst = &mut target.data[(y * width * target.nbands) as usize..];
        for x in 0..width {
            if let Some(&dist) = heman_image_texel(&seed, x, y) {
                if dist > mind && dist < maxd {
                    dst[0] = r;
                    dst[1] = g;
                    dst[2] = b;
                    if target.nbands == 4 {
                        dst[3] = a;
                    }
                }
            }
            dst = &mut dst[target.nbands as usize..];
        }
    }

    heman_points_destroy(&mut seed);
}

pub fn heman_color_apply_gradient(
    heightmap: &HemanImage,
    minheight: f32,
    maxheight: f32,
    gradient: &HemanImage,
) -> HemanImage {
    assert!(heightmap.nbands == 1, "heightmap->nbands == 1");
    assert!(gradient.height == 1, "gradient->height == 1");
    assert!(gradient.nbands == 3, "gradient->nbands == 3");

    let w = heightmap.width;
    let h = heightmap.height;
    let mut result = heman_image_create(w, h, 3);
    let size = result.height * result.width;
    let dst = &mut result.data;
    let src = &heightmap.data;
    let scale = 1.0 / (maxheight - minheight);

    for i in 0..size {
        let u = ((*src[i] - minheight) * scale).clamp(0.0, 1.0);
        heman_image_sample(gradient, u, 0.5, &mut dst[i * 3..i * 3 + 3]);
    }

    result
}

pub fn heman_points_from_density(
    density: &HemanImage,
    minradius: f32,
    maxradius: f32,
) -> HemanPoints {
    assert_eq!(density.nbands, 1, "density->nbands == 1");

    let width = 1.0;
    let height = 1.0;
    let maxattempts = 30;
    let rscale = 1.0 / (2147483647_u32.wrapping_mul(2) as f32 + 1.0);
    let mut seed = 0_u32;
    let rvec = KmVec2 { x: maxradius, y: maxradius };
    let cellsize = maxradius / f32::sqrt(2.0);
    let invcell = 1.0 / cellsize;
    let ncols = f32::ceil(width * invcell) as i32;
    let nrows = f32::ceil(height * invcell) as i32;
    let maxcol = ncols - 1;
    let maxrow = nrows - 1;
    let ncells = ncols * nrows;
    let ntexels = (cellsize * density.width as f32) as i32;
    let gcapacity = ntexels * ntexels;
    let mut grid = vec![0; (ncells * gcapacity) as usize];
    let mut ngrid = vec![0; ncells as usize];
    let mut actives = vec![0; ncells as usize];
    let mut nactives = 0;
    let maxsamples = ncells * gcapacity;
    let mut result = heman_image_create(maxsamples, 1, 2);
    let samples = &mut result.data;
    let mut nsamples = 0;
    let mut pt = KmVec2 {
        x: width * randhash(seed) as f32 * rscale,
        y: height * randhash(seed.wrapping_add(1)) as f32 * rscale,
    };
    seed = seed.wrapping_add(2);
    actives[nactives] = nsamples;
    nactives += 1;
    let gindex = ((pt.x * invcell) as i32 + ncols * (pt.y * invcell) as i32) as usize;
    grid[gcapacity as usize * gindex + ngrid[gindex] as usize] = nsamples;
    ngrid[gindex] += 1;
    samples[nsamples * 2] = pt.x;
    samples[nsamples * 2 + 1] = pt.y;
    nsamples += 1;

    while nsamples < maxsamples {
        let aindex = randhashf(seed, 0.0, nactives as f32).min(nactives as f32 - 1.0) as usize;
        seed = seed.wrapping_add(1);
        let sindex = actives[aindex];
        let mut found = false;
        let mut j = KmVec2 { x: 0.0, y: 0.0 };
        let mut minj = KmVec2 { x: 0.0, y: 0.0 };
        let mut maxj = KmVec2 { x: 0.0, y: 0.0 };
        let mut delta = KmVec2 { x: 0.0, y: 0.0 };

        for _ in 0..maxattempts {
            pt = sample_annulus(maxradius, KmVec2 { x: samples[sindex * 2], y: samples[sindex * 2 + 1] }, &mut seed);
            if pt.x < 0.0 || pt.x >= width || pt.y < 0.0 || pt.y >= height {
                continue;
            }
            minj = pt;
            maxj = pt;
            km_vec2_add(&mut maxj, &maxj, &rvec);
            km_vec2_subtract(&mut minj, &minj, &rvec);
            km_vec2_scale(&mut minj, &minj, invcell);
            km_vec2_scale(&mut maxj, &maxj, invcell);
            minj.x = minj.x.max(0.0).min(maxcol as f32);
            maxj.x = maxj.x.max(0.0).min(maxcol as f32);
            minj.y = minj.y.max(0.0).min(maxrow as f32);
            maxj.y = maxj.y.max(0.0).min(maxrow as f32);

            let mut reject = false;
            let mut densityval = 0.0;
            heman_image_sample(density, pt.x, pt.y, &mut densityval);
            densityval = f32::sqrt(densityval);
            let mindist = maxradius - densityval * (maxradius - minradius);
            let r2 = mindist * mindist;

            for j_y in minj.y as i32..=maxj.y as i32 {
                for j_x in minj.x as i32..=maxj.x as i32 {
                    let g_start = ((j_y * ncols + j_x) * gcapacity) as usize;
                    let g_end = g_start + ngrid[(j_y * ncols + j_x) as usize] as usize;
                    for g in g_start..g_end {
                        let entry = grid[g];
                        if entry != sindex {
                            km_vec2_subtract(&mut delta, &KmVec2 { x: samples[entry * 2], y: samples[entry * 2 + 1] }, &pt);
                            if km_vec2_length_sq(&delta) < r2 {
                                reject = true;
                                break;
                            }
                        }
                    }
                    if reject {
                        break;
                    }
                }
                if reject {
                    break;
                }
            }

            if reject {
                continue;
            }
            found = true;
            break;
        }

        if found && ngrid[((pt.x * invcell) as i32 + ncols * (pt.y * invcell) as i32) as usize] >= gcapacity {
            found = false;
        }

        if found {
            actives[nactives] = nsamples;
            nactives += 1;
            let gindex = ((pt.x * invcell) as i32 + ncols * (pt.y * invcell) as i32) as usize;
            grid[gcapacity as usize * gindex + ngrid[gindex] as usize] = nsamples;
            ngrid[gindex] += 1;
            samples[nsamples * 2] = pt.x;
            samples[nsamples * 2 + 1] = pt.y;
            nsamples += 1;
        } else {
            nactives -= 1;
            if nactives <= 0 {
                break;
            }
            actives[aindex] = actives[nactives];
        }
    }

    result.width = nsamples;
    result
}

pub fn heman_ops_stitch_horizontal(images: Vec<Arc<HemanImage>>, count: i32) -> HemanImage {
    assert!(count > 0, "count must be greater than 0");

    let width = images[0].width;
    let height = images[0].height;
    let nbands = images[0].nbands;

    for i in 1..count as usize {
        assert!(images[i].width == width, "all images must have the same width");
        assert!(images[i].height == height, "all images must have the same height");
        assert!(images[i].nbands == nbands, "all images must have the same number of bands");
    }

    let mut result = heman_image_create(width * count, height, nbands);

    (0..height).into_par_iter().for_each(|y| {
        for tile in 0..count {
            copy_row(&images[tile as usize], &mut result, tile * width, y);
        }
    });

    result
}

pub fn heman_generate_island_heightmap(width: i32, height: i32, seed: i64) -> HemanImage {
    let noisetex = heman_internal_generate_island_noise(width, height, seed);
    let mut coastmask = heman_image_create(width, height, 1);
    let data = &mut coastmask.data;
    let invh = 1.0 / height as f32;
    let invw = 1.0 / width as f32;
    let hh = height / 2;
    let hw = width / 2;

    (0..height).into_par_iter().for_each(|y| {
        let vv = (y - hh) as f32 * invh;
        let dst = &mut data[(y * width) as usize..((y + 1) * width) as usize];
        for x in 0..width {
            let mut n = [0.0; 3];
            let v = y as f32 * invh;
            let u = x as f32 * invw;
            heman_image_sample(&noisetex, u, v, &mut n);
            let u = (x - hw) as f32 * invw + n[1];
            let v = vv + n[2];
            let m = 0.707 - (u * u + v * v).sqrt() + n[0];
            dst[x as usize] = if m < SEALEVEL { 0.0 } else { 1.0 };
        }
    });

    let heightmap = heman_distance_create_sdf(&coastmask);
    heman_image_destroy(coastmask);
    let mut result = heman_image_create(width, height, 1);
    let data = &mut result.data;

    (0..height).into_par_iter().for_each(|y| {
        let dst = &mut data[(y * width) as usize..((y + 1) * width) as usize];
        for x in 0..width {
            let mut n = [0.0; 3];
            let u = x as f32 * invw;
            let v = y as f32 * invh;
            heman_image_sample(&noisetex, u, v, &mut n);
            let mut z = 0.0;
            heman_image_sample(&heightmap, u, v, &mut z);
            if z > 0.0 {
                let influence = z;
                let u = u + influence * n[1];
                let v = v + influence * n[2];
                heman_image_sample(&heightmap, u, v, &mut z);
                z += 6.0 * influence * n[0];
            }
            dst[x as usize] = z;
        }
    });

    heman_image_destroy(noisetex);
    heman_image_destroy(heightmap);
    result
}

pub fn heman_generate_archipelago_heightmap(
    width: i32,
    height: i32,
    points: &HemanPoints,
    noiseamt: f32,
    seed: i64,
) -> HemanImage {
    let noisetex = heman_internal_generate_island_noise(width, height, seed);
    let mut coastmask = heman_image_create(width, height, 1);
    heman_image_clear(&mut coastmask, 0.0);
    heman_internal_draw_seeds(&mut coastmask, points, 1);

    let invh = 1.0 / height as f32;
    let invw = 1.0 / width as f32;
    let hh = height / 2;
    let hw = width / 2;

    coastmask.data.par_chunks_mut(width as usize).enumerate().for_each(|(y, dst)| {
        let vv = (y as i32 - hh) as f32 * invh;
        for x in 0..width {
            let mut n = [0.0; 3];
            let v = y as f32 * invh;
            let u = x as f32 * invw;
            heman_image_sample(&noisetex, u, v, &mut n);
            let mut u = (x as i32 - hw) as f32 * invw;
            let mut v = vv;
            u += noiseamt * n[1];
            v += noiseamt * n[2];
            let mut m = dst[x as usize];
            m += noiseamt * n[0];
            dst[x as usize] = if m < SEALEVEL { 0.0 } else { 1.0 };
        }
    });

    let heightmap = heman_distance_create_sdf(&coastmask);
    heman_image_destroy(coastmask);

    let mut result = heman_image_create(width, height, 1);
    result.data.par_chunks_mut(width as usize).enumerate().for_each(|(y, dst)| {
        for x in 0..width {
            let mut n = [0.0; 3];
            let u = x as f32 * invw;
            let v = y as f32 * invh;
            heman_image_sample(&noisetex, u, v, &mut n);
            let mut z = 0.0;
            heman_image_sample(&heightmap, u, v, &mut z);
            if z > 0.0 {
                let influence = z;
                let mut u = u + influence * n[1];
                let mut v = v + influence * n[2];
                heman_image_sample(&heightmap, u, v, &mut z);
                z += 6.0 * influence * n[0];
            }
            dst[x as usize] = z;
        }
    });

    heman_image_destroy(noisetex);
    heman_image_destroy(heightmap);

    result
}

