pub fn heman_lighting_apply(
    heightmap: &HemanImage,
    albedo: Option<&HemanImage>,
    occlusion: f32,
    diffuse: f32,
    diffuse_softening: f32,
    light_position: Option<&[f32; 3]>,
) -> HemanImage {
    assert_eq!(heightmap.nbands, 1, "heightmap->nbands == 1");
    let width = heightmap.width;
    let height = heightmap.height;
    let mut final_image = heman_image_create(width, height, 3);
    let normals = heman_lighting_compute_normals(heightmap);
    let occ = heman_lighting_compute_occlusion(heightmap);

    if let Some(albedo) = albedo {
        assert_eq!(albedo.nbands, 3, "albedo->nbands == 3");
        assert_eq!(albedo.width, width, "albedo->width == width");
        assert_eq!(albedo.height, height, "albedo->height == height");
    }

    let default_pos = [-0.5f32, 0.5f32, 1.0f32];
    let light_position = light_position.unwrap_or(&default_pos);

    let colors = Arc::new(Mutex::new(&mut final_image.data));
    let invgamma = 1.0 / GAMMA;
    let mut L = KmVec3 {
        x: light_position[0],
        y: light_position[1],
        z: light_position[2],
    };
    km_vec3_normalize(&mut L, &L);

    (0..height).into_par_iter().for_each(|y| {
        let mut colors = colors.lock().unwrap();
        let color_start = y * width * 3;
        for x in 0..width {
            let color_index = color_start + x * 3;
            let N = heman_image_texel(&normals, x, y).unwrap();
            let mut N_vec = KmVec3 {
                x: N[0],
                y: N[1],
                z: N[2],
            };
            km_vec3_lerp(&mut N_vec, &N_vec, &KM_VEC3_POS_Z, diffuse_softening);
            let df = 1.0 - diffuse * (1.0 - km_clamp(km_vec3_dot(&N_vec, &L), 0.0, 1.0));
            let of = 1.0 - occlusion * (1.0 - heman_image_texel(&occ, x, y).unwrap()[0]);

            if let Some(albedo) = albedo {
                let albedo_texel = heman_image_texel(albedo, x, y).unwrap();
                colors[color_index] = albedo_texel[0];
                colors[color_index + 1] = albedo_texel[1];
                colors[color_index + 2] = albedo_texel[2];
            } else {
                colors[color_index] = 1.0;
                colors[color_index + 1] = 1.0;
                colors[color_index + 2] = 1.0;
            }

            colors[color_index] = colors[color_index].powf(GAMMA);
            colors[color_index + 1] = colors[color_index + 1].powf(GAMMA);
            colors[color_index + 2] = colors[color_index + 2].powf(GAMMA);

            let mut color_vec = KmVec3 {
                x: colors[color_index],
                y: colors[color_index + 1],
                z: colors[color_index + 2],
            };
            km_vec3_scale(&mut color_vec, &color_vec, df * of);

            colors[color_index] = color_vec.x.powf(invgamma);
            colors[color_index + 1] = color_vec.y.powf(invgamma);
            colors[color_index + 2] = color_vec.z.powf(invgamma);
        }
    });

    heman_image_destroy(normals);
    heman_image_destroy(occ);
    final_image
}
